// Flags each item with:
//  - isNew: true the first time this executionId is ever seen by this workflow
//  - circuitBroken: true if this workflow has failed >3 times in the last hour
// Persisted in this workflow's static data so it survives between runs
// without needing an external database.

const staticData = $getWorkflowStaticData('global');
if (!staticData.seenExecutionIds) staticData.seenExecutionIds = [];

const items = $input.all();
const nowMs = Date.now();
const ONE_HOUR = 60 * 60 * 1000;

const countsByWorkflow = {};
for (const item of items) {
  const startedAtMs = new Date(item.json.startedAt).getTime();
  if (nowMs - startedAtMs <= ONE_HOUR) {
    const key = item.json.workflow;
    countsByWorkflow[key] = (countsByWorkflow[key] || 0) + 1;
  }
}

const seen = new Set(staticData.seenExecutionIds);

for (const item of items) {
  const id = item.json.executionId;
  item.json.isNew = !seen.has(id);
  seen.add(id);
  item.json.circuitBroken = (countsByWorkflow[item.json.workflow] || 0) > 3;
}

// Cap stored history so static data doesn't grow unbounded.
staticData.seenExecutionIds = [...seen].slice(-500);

return items;

// Sends a real Web Push notification to every subscribed browser using
// the 'web-push' npm package. This ONLY works on self-hosted n8n with:
//   NODE_FUNCTION_ALLOW_EXTERNAL=web-push
// set as an environment variable, and `npm install web-push` run inside
// the n8n installation. n8n Cloud's sandboxed Code node cannot require()
// external packages, so push will silently no-op there — see SETUP.md.
//
// Requires N8N env vars: VAPID_PUBLIC_KEY, VAPID_PRIVATE_KEY
// (generate with: npx web-push generate-vapid-keys)

const staticData = $getWorkflowStaticData('global');
const subscriptions = staticData.pushSubscriptions || [];
if (subscriptions.length === 0) return [];

let webpush;
try {
  webpush = require('web-push');
} catch (e) {
  return []; // web-push isn't installed/allowed in this n8n environment
}

webpush.setVapidDetails(
  'mailto:you@example.com',
  $env.VAPID_PUBLIC_KEY,
  $env.VAPID_PRIVATE_KEY
);

const items = $input.all();
const stillValid = [];

for (const sub of subscriptions) {
  let expired = false;
  for (const item of items) {
    const payload = JSON.stringify({
      title: 'Where Did It Break?',
      body: `${item.json.client}: ${item.json.translation || (item.json.workflow + ' failed')}`,
      url: './'
    });
    try {
      await webpush.sendNotification(sub, payload);
    } catch (err) {
      if (err.statusCode === 404 || err.statusCode === 410) expired = true;
    }
  }
  if (!expired) stillValid.push(sub);
}

staticData.pushSubscriptions = stillValid;
return items;

// Stores the browser's PushSubscription object in this workflow's static
// data, keyed by endpoint so re-subscribing doesn't create duplicates.
// Shared static data is why this endpoint lives in the SAME n8n workflow
// as Send Push Notifications above (static data is per-workflow, not global).

const staticData = $getWorkflowStaticData('global');
if (!staticData.pushSubscriptions) staticData.pushSubscriptions = [];

const sub = $input.first().json.body;
const exists = staticData.pushSubscriptions.some(s => s.endpoint === sub.endpoint);
if (!exists && sub && sub.endpoint) {
  staticData.pushSubscriptions.push(sub);
}

return [{ json: { success: true } }];
